package lk.sahan.parking.desktop;
import com.fasterxml.jackson.databind.JsonNode;
import javafx.application.Platform;
import javafx.collections.ObservableList;
import javafx.scene.control.*;
import javafx.scene.layout.VBox;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import java.math.BigDecimal;

final class CorrectionsPane {
 private final ApiClient api;private final ExecutorService io;private final BooleanSupplier active;private final PendingCheckoutStore store;
 private final TextField paymentId=new TextField(),amount=new TextField(),reference=new TextField();private final TextArea reason=new TextArea();private final Label original=Ui.text("Load the original payment first.","muted"),feedback=Ui.notice(),paging=Ui.text("","muted");
 private final ComboBox<String> type=new ComboBox<>();private final ComboBox<JsonNode> shift=new ComboBox<>(),branch;private final DatePicker from=new DatePicker(),to=new DatePicker();
 private final CheckBox confirmed=new CheckBox("I confirm this correction and its reason."),notCollected=new CheckBox("VOID: No money was collected or settlement did not occur."),external=new CheckBox("I confirmed the correction on the external terminal. This app does not transfer money.");
 private final TableView<JsonNode> table=new TableView<>();private final VBox view;private JsonNode payment;private boolean busy;private int page,pages;
 CorrectionsPane(ApiClient api,ExecutorService io,ObservableList<JsonNode> branches,BooleanSupplier active){
  this.api=api;this.io=io;this.active=active;store=new PendingCheckoutStore(api,"correction");branch=new ComboBox<>(branches);branch.setPromptText("All branches");branch.setCellFactory(c->branchCell());branch.setButtonCell(branchCell());
  type.getItems().setAll("REFUND","VOID");type.setValue("REFUND");paymentId.setPromptText("Original payment / receipt ID");amount.setPromptText("Correction amount · LKR");reference.setPromptText("External correction reference");reason.setPrefRowCount(3);reason.setWrapText(true);external.setWrapText(true);notCollected.setWrapText(true);confirmed.setWrapText(true);
  shift.setPromptText("Active shift paying cash refund");shift.setCellFactory(c->shiftCell());shift.setButtonCell(shiftCell());
  Button load=Ui.button("Load original payment","secondary"),record=Ui.button("Record correction","danger"),pending=Ui.button("Pending correction attempts","secondary"),refresh=Ui.button("Search history","primary"),previous=Ui.button("Previous","secondary"),next=Ui.button("Next","secondary"),clear=Ui.button("All branches","secondary");
  load.setOnAction(e->loadPayment());record.setOnAction(e->record());refresh.setOnAction(e->{page=0;activate();});previous.setOnAction(e->{if(page>0){page--;activate();}});next.setOnAction(e->{if(page+1<pages){page++;activate();}});clear.setOnAction(e->branch.setValue(null));
  pending.setOnAction(e->call(store::tickets,ids->{if(ids.isEmpty()){Ui.notice(feedback,"No pending corrections.",false);return;}ChoiceDialog<Long> pick=new ChoiceDialog<>(ids.get(0),ids);Ui.dialog(pick,view().getScene().getWindow());pick.setHeaderText("Choose payment to check the saved correction attempt");pick.showAndWait().ifPresent(id->{paymentId.setText(id.toString());recover(id);});},this::failed));
  table.getColumns().setAll(Ui.column("Correction","id",80),Ui.column("Original payment","paymentId",110),Ui.column("Type","type",90),Ui.column("Amount · LKR","amount",115),Ui.column("Original paid","originalPaidAt",170),Ui.column("Correction date","occurredAt",170),Ui.column("Branch","branch",155),Ui.column("Actor","actor",120),Ui.column("Reason","reason",160));Ui.table(table,"Load correction history.",300);Ui.fillColumns(table);
  view=Ui.page(Ui.section("Payment corrections","Original payments and closed parking sessions remain unchanged. Refund = money returned; Void = full reversal of an uncollected/unsettled payment. Do not record a terminal refund twice.",Ui.flow(Ui.field("Original payment ID",paymentId),load,pending),original,
   Ui.flow(Ui.field("Correction type",type),Ui.field("Amount · LKR",amount),Ui.field("Cash refund shift",shift)),Ui.field("Required reason",reason),Ui.field("External terminal correction reference",reference),notCollected,external,confirmed,record,feedback),
   Ui.section("Correction history","Collections use the original payment date; corrections affect their own occurrence date and refund shift. Closed original shift totals stay fixed.",Ui.flow(Ui.field("Branch",branch),clear,Ui.field("From correction date",from),Ui.field("To correction date",to),refresh),table,Ui.flow(previous,paging,next)));
 }
 VBox view(){return view;}
 private ListCell<JsonNode> branchCell(){return new ListCell<>(){@Override protected void updateItem(JsonNode r,boolean empty){super.updateItem(r,empty);setText(empty||r==null?"All branches":r.path("code").asText()+" · "+r.path("name").asText());}};}
 private ListCell<JsonNode> shiftCell(){return new ListCell<>(){@Override protected void updateItem(JsonNode r,boolean empty){super.updateItem(r,empty);setText(empty||r==null?"No refund shift":"#"+r.path("id").asText()+" · "+r.path("cashier").asText()+" · cash "+r.path("expectedCash").asText());}};}
 interface Work<T>{T run()throws Exception;}
 private <T>void call(Work<T> work,Consumer<T> success,Consumer<Throwable> failure){if(busy)return;busy=true;CompletableFuture.supplyAsync(()->{try{return work.run();}catch(Exception ex){throw new CompletionException(ex);}},io).whenComplete((result,error)->Platform.runLater(()->{busy=false;if(!api.isActive()||!active.getAsBoolean())return;if(error==null)success.accept(result);else failure.accept(error.getCause());}));}
 private void failed(Throwable error){Ui.notice(feedback,error.getMessage(),true);}
 private void loadPayment(){long id;try{id=Long.parseLong(paymentId.getText().trim());}catch(Exception ex){Ui.notice(feedback,"Enter an original payment ID.",true);return;}
  call(()->List.of(api.get("/api/admin/payments/"+id),api.get("/api/admin/payments/"+id+"/refund-shifts")),rows->{payment=rows.get(0);original.setText(ParkingDialogs.receiptBody(payment)+"\nRemaining uncorrected amount: LKR "+payment.path("netAmount").asText());amount.setText(payment.path("netAmount").asText());shift.getItems().clear();rows.get(1).forEach(shift.getItems()::add);if(!shift.getItems().isEmpty())shift.setValue(shift.getItems().get(0));Ui.notice(feedback,"Confirm physical cash/terminal status before recording. No funds are transferred by this application.",false);},this::failed);
 }
 private void record(){if(payment==null){Ui.notice(feedback,"Load the original payment first.",true);return;}long id=payment.path("paymentId").asLong();Map<String,String> request=new HashMap<>();
  try{request.put("requestKey",UUID.randomUUID().toString());request.put("type",type.getValue());request.put("amount",new BigDecimal(amount.getText()).toPlainString());request.put("reason",reason.getText().trim());request.put("confirmed",String.valueOf(confirmed.isSelected()));request.put("notCollectedConfirmed",String.valueOf(notCollected.isSelected()));request.put("externalReference",reference.getText().trim());request.put("externalConfirmed",String.valueOf(external.isSelected()));if(type.getValue().equals("REFUND")&&payment.path("method").asText().equals("CASH")&&shift.getValue()!=null)request.put("movementShiftId",shift.getValue().path("id").asText());}catch(Exception ex){Ui.notice(feedback,"Enter a valid amount.",true);return;}
  if(!confirmed.isSelected()){Ui.notice(feedback,"Explicit confirmation is required.",true);return;}
  call(()->store.get(id),saved->{if(saved!=null){check(id,saved);return;}Alert confirm=new Alert(Alert.AlertType.CONFIRMATION,"Record "+request.get("type")+" of LKR "+request.get("amount")+" for payment #"+id+"? The original payment will remain immutable.",ButtonType.OK,ButtonType.CANCEL);Ui.dialog(confirm,view().getScene().getWindow());confirm.showAndWait().filter(b->b==ButtonType.OK).ifPresent(b->post(id,request));},this::failed);
 }
 private void recover(long id){call(()->store.get(id),saved->{if(saved==null)Ui.notice(feedback,"No pending attempt for this payment.",false);else check(id,saved);},this::failed);}
 private void check(long id,Map<String,String> saved){call(()->api.get("/api/admin/correction-attempts/"+saved.get("requestKey")),result->complete(id,result),error->{if(error instanceof ApiClient.HttpFailure http&&http.statusCode()==404){Alert retry=new Alert(Alert.AlertType.CONFIRMATION,"No committed correction found. Retry the same saved "+saved.get("type")+" for LKR "+saved.get("amount")+" with its original key and details?",ButtonType.OK,ButtonType.CANCEL);Ui.dialog(retry,view().getScene().getWindow());retry.showAndWait().filter(b->b==ButtonType.OK).ifPresent(b->post(id,saved));}else Ui.notice(feedback,"Outcome uncertain; saved correction preserved. "+error.getMessage(),true);});}
 private void post(long id,Map<String,String> request){call(()->{store.save(id,request);return api.post("/api/admin/payments/"+id+"/corrections",request);},result->complete(id,result),error->{
  if(error instanceof ApiClient.HttpFailure http&&(http.statusCode()==400||http.statusCode()==409&&http.details()!=null&&http.details().path("code").asText().equals("CORRECTION_REJECTED")))call(()->{store.clear(id);return true;},ignored->Ui.notice(feedback,http.getMessage()+" No correction committed by this attempt.",true),this::failed);
  else Ui.notice(feedback,"Outcome may be uncertain. Use Pending correction attempts; the same key and details are preserved. "+error.getMessage(),true);
 });}
 private void complete(long id,JsonNode result){call(()->{store.clear(id);return result;},r->{confirmed.setSelected(false);notCollected.setSelected(false);external.setSelected(false);reason.clear();reference.clear();Ui.notice(feedback,"Correction #"+r.path("id").asText()+" recorded. Reload the original payment to view its updated correction history.",false);ThermalDocuments.text("Payment correction",r.toPrettyString(),view().getScene().getWindow());activate();},error->Ui.notice(feedback,"Correction is recorded; local recovery metadata could not be cleared. Checking it again is safe.",true));}
 void activate(){String path="/api/admin/corrections?page="+page;if(branch.getValue()!=null)path+="&branchId="+branch.getValue().path("id").asLong();if(from.getValue()!=null)path+="&from="+from.getValue();if(to.getValue()!=null)path+="&to="+to.getValue();String url=path;call(()->api.get(url),rows->{table.getItems().clear();rows.path("rows").forEach(table.getItems()::add);pages=rows.path("pages").asInt();paging.setText("Page "+(page+1)+" / "+Math.max(1,pages));},this::failed);}
}
